T[8470]={name="El tótem ritual de los Muertobosque",objectivesText={"Lleva el tótem ritual Muertobosque al interior del Bastión de los Fauces de Madera. A ver si alguno de los furbolgs que hay en él sabe dar uso al objeto. Los Fauces de Madera no hablarán contigo si no tienes un nivel de reputación neutral o superior con ellos."}}
T[8471]={name="Tótem ritual Nevada",objectivesText={"Lleva el tótem ritual Nevada al Bastión de los Fauces de Madera y averigua si alguno de los furbolgs sabe de su utilidad. Los Fauces de Madera no hablarán contigo si tu reputación con ellos no es como mínimo de neutral."}}
T[8481]={name="La raíz de todos los males",objectivesText={"Clava la antorcha de invocación del Demonio en la entrada de la cueva del Gran Jefe Nevada en el Poblado Nevada de los furbolgs. Derrota al demonio y consigue la esencia de Xandivious para Gorn Monóculo del Bastión de los Fauces de Madera."}}
T[8484]={name="Negociar la paz",objectivesText={"Llévale la ofrenda de paz de los Fauces de Madera al rey Magni Barbabronce de Forjaz."}}
T[8485]={name="Negociar la paz",objectivesText={"Llévale la ofrenda de paz de los Fauces de Madera a Thrall, que está en Orgrimmar."}}
T[8492]={name="¡La Alianza necesita lingotes de cobre!",objectivesText={"Llévale 20 lingotes de cobre al alférez Petrocejas en La Sala Militar de Forjaz."}}
T[8493]={name="¡La Alianza necesita más lingotes de cobre!",objectivesText={"Llévale 20 lingotes de cobre al sargento Petrocejas en la base aérea de Dun Morogh."}}
T[8494]={name="¡La Alianza necesita lingotes de hierro!",objectivesText={"Llévale 20 lingotes de hierro al cabo Carnes en La Sala Militar de Forjaz."}}
T[8495]={name="¡La Alianza necesita más lingotes de hierro!",objectivesText={"Llévale 20 lingotes de hierro al cabo Carnes en la base aérea de Dun Morogh."}}
T[8496]={name="Vendas para el campo de batalla",objectivesText={"Lleva 30 vendas de paño rúnico gruesas, 30 vendas de seda gruesas y 30 vendas de tejido mágico gruesas a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión."}}
T[8497]={name="Material de supervivencia en el desierto"}
T[8498]={name="Órdenes de batalla de Crepusculares",objectivesText={"Consigue las órdenes de batalla de Crepusculares y llévaselas al comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas tácticas X para poder completar la misión."}}
