T[8504]={name="¡La Alianza necesita más algas estranguladoras!",objectivesText={"Llévale 20 algas estranguladoras al soldado Draxlegauge en la base aérea de Dun Morogh."}}
T[8505]={name="¡La Alianza necesita lotos cárdenos!",objectivesText={"Llévale 20 lotos cárdenos al maestro Arrullanoche en La Sala Militar de Forjaz."}}
