T[8534]={name="Informe de exploración de Colmen'Zora",objectivesText={"Contacta con la exploradora Cenarion Azenel en Colmen'Zora y entrega el informe de exploración de Colmen'Zora a Astaorgullo Clamavientos en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VI para poder completar la misión."}}
T[8535]={name="Templario vetusto",objectivesText={"Invoca y mata a un Templario vetusto y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas IV para poder completar la misión."}}
T[8536]={name="Templario de tierra",objectivesText={"Invoca y mata a un Templario de tierra y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas III para poder completar la misión."}}
T[8537]={name="Templario carmesí",objectivesText={"Invoca y mata a un Templario carmesí y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas II para poder completar la misión."}}
T[8538]={name="Los cuatro Duques",objectivesText={"Invoca y mata al Duque de las Brasas, al Duque de las Profundidades, al Duque de los Céfiros y al Duque de las Esquirlas y preséntate ante la comandante Mar'alith en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas V para poder completar la misión."}}
T[8539]={name="Objetivo: las hermanas de la colmena de Colmen'Zora",objectivesText={"Mata 30 hermanas de la colmena de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate V para poder completar la misión."}}
T[8540]={name="Botas para la guardia",objectivesText={"Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión."}}
T[8541]={name="Piedra de pulir para la guardia",objectivesText={"Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión."}}
T[8542]={name="¡La Horda necesita lingotes de estaño!",objectivesText={"Llévale 20 lingotes de estaño a Bruto Maug en el Valle de los Espíritus de Orgrimmar."}}
