T[8548]={name="Equipamiento de Voluntario",objectivesText={"Lleva 5 distintivos de combate Cenarion, 3 distintivos de logística Cenarion y 7 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación amistoso con el Círculo Cenarion para poder completar esta misión."}}
T[8549]={name="¡La Horda necesita flores de paz!",objectivesText={"Llévale 20 flores de paz al herborista Plumorgullo en el Valle de los Espíritus de Orgrimmar."}}
T[8550]={name="¡La Horda necesita más flores de paz!"}
T[8551]={name="El cofre del capitán",objectivesText={"Lleva el cofre de Smotts a Hecklebury Smotts en la Bahía del Botín."}}
T[8552]={name="La banda con monograma",objectivesText={"Devuelve la banda con monograma a su propietario."}}
T[8553]={name="El aflanje del capitán",objectivesText={"Habla con Sprogger."}}
T[8554]={name="Enfréntate a Negolash",objectivesText={"Lleva 10 Alas de águila ratonera a la parrilla y 5 botellas de vino de vid de jungla al barco salvavidas del capitán Smotts.","","Mata a Negolash y lleva el alfanje de Smotts al capitán Smotts en Tuercespina."}}
T[8555]={name="Encomienda a los Vuelos"}
T[8556]={name="El anillo con sello de fuerza implacable",objectivesText={"Llévale 1 anillo de magistrado qiraji, 2 ídolos luminiscentes, 5 escarabajos de bronce y 5 escarabajos de marfil a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honrado ante el Círculo Cenarion para completar esta misión."}}
