T[8577]={name="Stewvul, ex mejor amigo",objectivesText={"Narain Sabelotodo quiere que encuentres a su ex mejor amigo de toda la vida, Guisón, y que recuperes las gafas que le robó."}}
T[8578]={name="¿Unas gafas? ¡Sin problemas!",objectivesText={"Encuentra las gafas de visión de Narain y llévaselas a Tanaris."}}
