T[8770]={name="Objetivo: los defensores de Colmen'Ashi",objectivesText={"Mata 30 defensores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate I para poder completar la misión."}}
T[8771]={name="Objetivo: los acecharenas de Colmen'Ashi",objectivesText={"Mata 30 acecharenas Colmen'Ashi y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate II para poder completar la misión."}}
T[8772]={name="Objetivo: los oteadores de Colmen'Zora",objectivesText={"Mata 30 oteadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VI para poder completar la misión.|n"}}
T[8773]={name="Objetivo: los atracadores de Colmen'Zora",objectivesText={"Mata 30 atracadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IV para poder completar la misión."}}
T[8774]={name="Objetivo: los emboscadores de Colmen'Regal",objectivesText={"Mata 30 emboscadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VIII para poder completar la misión."}}
T[8775]={name="Objetivo: los escupefuego de Colmen'Regal",objectivesText={"Mata 30 escupefuegos Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IX para poder completar la misión."}}
T[8776]={name="Objetivo: los esclavizadores de Colmen'Regal",objectivesText={"Mata 30 esclavizadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate X para poder completar la misión."}}
T[8777]={name="Objetivo: los hurgadores de Colmen'Regal",objectivesText={"Mata 30 hurgadores Colmen'Regal y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XI para poder completar la misión."}}
T[8778]={name="La Brigada de Forjaz necesita explosivos",objectivesText={"Lleva 6 aceites de inmolación, 5 unidades de combustible de cohete goblin y 10 unidades de pólvora densa al arcanista Bocafuente cerca de Colmen'Zora en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}}
T[8779]={name="Materiales de visión",objectivesText={"Lleva 1 fragmento grande brillante, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión."}}
T[8780]={name="Refuerzos para armadura para el campo de batalla",objectivesText={"Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, cerca de Colmen'Zora, en Silithus. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}}
T[8781]={name="Armas para el campo de batalla",objectivesText={"Lleva 2 espadas anchas de acero lunar a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, en las afueras de Colmen'Zora. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}}
T[8782]={name="Suministros para uniformes",objectivesText={"Lleva 1 unidad de tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Astaorgullo Clamavientos en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión."}}
T[8783]={name="Materiales encantados",objectivesText={"Lleva 2 lingotes de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión."}}
T[8784]={name="Los secretos de los qiraji",objectivesText={"Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo.|n"}}
T[8785]={name="¡La Legión de Orgrimmar necesita mojo!",objectivesText={"Lleva 6 unidades de mojo potente, 6 frascos de mojo grande y 8 aceites de inmolación a la sacerdotisa de las Sombras Shai cerca de Colmen'Regal, en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}}
T[8786]={name="Armas para el campo de batalla",objectivesText={"Lleva 3 hachas de hierro macizo a Merok Zancada Larga en el campamento de la Legión de Orgrimmar, en las afueras de Colmen'Regal. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}}
T[8787]={name="Complementos para armadura para el campo de batalla",objectivesText={"Lleva 8 complementos bastos para armadura y 8 complementos pesados para armadura a Merok Zancolargo, cerca de Colmen'Regal. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}}
T[8788]={name="Un obsequio ligeramente agitado"}
T[8789]={name="Armamentos imperiales qiraji",objectivesText={"Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas armamento imperial qiraji y 3 menas de elementium."}}
T[8790]={name="Regalos imperiales Qiraji",objectivesText={"Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de Elementium para ti si le llevas regalos imperiales qiraji y 3 minerales de Elementium."}}
T[8791]={name="La caída de Osirio",objectivesText={"Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus.|n"}}
