T[9121]={name="La ciudadela del terror: Naxxramas",objectivesText={"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 cristales Arcanos, 2 cristales nexo, 1 orbe recto y 60 piezas de oro. También tienes que ser Honorable con El Alba Argenta.|n"}}
T[9122]={name="La ciudadela del terror: Naxxramas",objectivesText={"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 2 cristales Arcanos, 1 cristal nexo y 30 piezas de oro. También tienes que ser Venerado con El Alba Argenta."}}
T[9123]={name="La ciudadela del terror: Naxxramas",objectivesText={"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, se ofrece a costear tu velo Arcano. Debes ser Exaltado con El Alba Argenta."}}
T[9124]={name="La armadura de acechacriptas no se hace sola...",objectivesText={"El montero Leopold, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 trozos de maligno de cripta."}}
