T[9142]={name="Libranza del artesano"}
T[9153]={name="Bajo la Sombra",objectivesText={"Busca en tu mapa una zona que esté bajo el ataque de la Plaga. Ve y derrota a los miembros de la Plaga que custodian la necrópolis. Lleva 10 runas necróticas al comandante Thomas Helleran a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
T[9154]={name="Capilla de la Esperanza de la Luz",objectivesText={"Lleva la llamada a las armas al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
