T[9248]={name="Una humilde ofrenda",objectivesText={"Aurel Hojaurea quiere que le lleves 1 cetro abisal al Fuerte Cenarion, en Silithus. También deben considerarte honorable con el Círculo Cenarion."}}
T[9250]={name="Cuerpo de Atiesh",objectivesText={"Busca a alguien que te ayude a buscar las dos piezas del báculo que faltan y a exorcizar el bastón."}}
