T[92748]={name="Consultoría explosiva",objectivesText={"Viaja al Distrito de los Enanos de Ventormenta y busca a algún ingeniero que pueda ayudarte."}}
T[92749]={name="Un plan explosivo",objectivesText={"Consigue 10 unidades de dinamita férrea mediante fabricación, comercio o en la casa de subastas y luego vuelve con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta."}}
T[92750]={name="Detonación a distancia",objectivesText={"Habla con alguien del servicio secreto de Ventormenta para conseguir un detonador a distancia."}}
T[92751]={name="Detonación a distancia",objectivesText={"Llévale el equipo de detonador a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta."}}
T[92752]={name="Consultoría explosiva",objectivesText={"Vuelve con Alba Lunajusta en los Páramos de Poniente."}}
T[92753]={name="Destrucción en las Minas de la Muerte",objectivesText={"Encuentra la forja oculta en las Minas de la Muerte y coloca los explosivos extradestructivos cerca. Luego, reúnete con Alba Lunajusta en la salida de las minas."}}
T[92754]={name="Se necesita protección contra las Sombras",objectivesText={"Mantén tu reputación con los Magram y lleva 3 pociones de protección contra las Sombras superiores a Mirda en el Poblado Magram de Desolace."}}
T[92755]={name="Misticismo enigmático"}
T[92811]={name="Guerra económica"}
T[92812]={name="Guerra económica"}
T[92814]={name="Necesito un sastre"}
T[92817]={name="Técnica de cuero",objectivesText={"Mantén tu reputación con los Gelkis, y lleva un arnés barbárico a Talra en el Poblado Gelkis de Desolace."}}
T[92818]={name="Hachas de hierro grandes... No, gigantes",objectivesText={"Mantén tu reputación con los Magram y llévale 2 hachas de hierro gigantes a Grolkar en el Poblado Magram, en Desolace."}}
T[92819]={name="Destrucción en las Minas de la Muerte",objectivesText={"Utiliza el detonador."}}
T[92834]={name="Venganza desmedida",objectivesText={"Consigue 10 talismanes de piedra de viento de los cultores Al'Aketh que se encuentran al norte de Valanaar, en los campos de los Soplabayas o en el Santuario de Akir."}}
T[92840]={name="Estudiar el viento",objectivesText={"Lleva el Index Esoteria a las Piedras verticales del mirador de las Tierras Altas de Shen'dar y úsalo con las formaciones de piedras de viento de la zona para recopilar datos."}}
T[92841]={name="Valle de los Huesos",objectivesText={"Mejora tu reputación con los Magram y ubica a Orgrul cerca del Valle de los Huesos, al sur del Poblado Magram."}}
T[92844]={name="Montaña de huesos",objectivesText={"Mantén tu reputación con los Magram y lleva 426 huesos ligeramente malditos a Orgrul, al sur del Poblado Magram en Desolace."}}
T[92846]={name="Nigromantes marginadas",objectivesText={"Mantén tu reputación con los Magram y mata a nigromantes marginadas en el Valle de los Huesos."}}
T[92847]={name="Lágrimas corruptas",objectivesText={"Mantén tu reputación con los Magram, y lleva 3 corteza petrificada y 3 lágrimas imbuidas a Orgrul."}}
T[92849]={name="El erudito desaparecido",objectivesText={"Sigue buscando a Fillion Brisallama."}}
T[92850]={name="El erudito desaparecido",objectivesText={"Mata a la matriarca chilladora en su guarida y luego entrega su cabeza a Fillion Brisallama, en Valanaar."}}
T[92860]={name="Al servicio de Zephras",objectivesText={"Informa a Valennia Puñotormenta y dile que la Orden Eminente la apoya en su lucha contra los Al'Aketh."}}
T[92867]={name="Una tierra que proteger",objectivesText={"Derrota a los intrusos Puño de Roca, de la Hermandad y de los Secacorteza en el Castillo de Stromgarde. Después, vuelve con el guardés Lomar."}}
T[92871]={name="Al servicio de Zephras",objectivesText={"Informa a Valennia Puñotormenta y dile que los Formavientos la apoyan en su lucha contra los Al'Aketh."}}
T[92872]={name="Pasos obedientes",objectivesText={"Lanza la faltriquera de polvo de tumba al Mare Magnum y vuelve a ver al cuidador Alaric en la cripta del Castillo de Stromgarde."}}
T[92880]={name="Regreso a Valanaar",objectivesText={"Llévale el informe de Yorna a Valennia Puñotormenta en Valanaar."}}
T[92881]={name="La petición del sumo anciano",objectivesText={"Ve a Valanaar y habla con Talaanis Cantosombrío."}}
T[92909]={name="Cosechar a los cosechadores",objectivesText={"Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 14 isomuelles de gólem y 5 giroestabilizadores de cosechador."}}
T[92910]={name="Cosechar a los cosechadores",objectivesText={"Llévale el chasis de autocognición precesiva a Ozwin Ferropiñón, en la Granja de Saldean."}}
T[92911]={name="Cosechar a los cosechadores",objectivesText={"Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 8 isomuelles de gólem, 4 moduladores de cobre y una mira rudimentaria."}}
T[92914]={name="Pilones extraños",objectivesText={"Explora Shen'dralas en busca de otros pilones como el que encontraste."}}
T[92947]={name="Es nuestro turno",objectivesText={"Acaba con 7 guardianes de Al'Aketh, 7 clamaespíritus de Al'Aketh y 7 maestros del acero de Al'Aketh, y luego informa a Hyusaa Brisa Presta en el Santuario de Akir."}}
T[93016]={name="Una breve lección de historia",objectivesText={"Habla con Mordent Sombrapar en Shen'dralas y pídele información sobre los cristales que reparaste."}}
T[93034]={name="Valle de los Huesos",objectivesText={"Mejora tu reputación con los Gelkis y localiza a Nerlokh cerca del Valle de los Huesos, al este del Poblado Gelkis."}}
T[93035]={name="Devastadores devastando",objectivesText={"Mantén tu reputación con el clan Gelkis y mata a 6 devastadores no-muertos. Luego, vuelve con Nerlokh en la entrada sur del Valle de los Huesos."}}
T[93036]={name="Infiltrarse en el culto",objectivesText={"Habla con Sania Torrenteplata en la Aldea Shen'dar."}}
T[93037]={name="Marginados al descubierto",objectivesText={"Mantén tu reputación con el clan Gelkis y llévale 1 atuendo nigromántico a Nerlokh, en la entrada del Valle de los Huesos."}}
T[93065]={name="Preparativos para la batalla",objectivesText={"Habla con Valennia Puñotormenta en las Tierras Bajas de los Soplabayas."}}
T[93089]={name="Lo que está por venir",objectivesText={"Habla con Elaadrin Vendaval del Atardecer para partir de la Isla de Zephras."}}
T[93090]={name="Lo que está por venir",objectivesText={"Habla con Ayessa Cantoalba cuando estés preparada para marcharte de la Isla de Zephras."}}
T[93159]={name="El ermitaño extraño",objectivesText={"Habla con el ermitaño extraño en el Bosque Ventosombra y averigua más cosas sobre él."}}
T[93160]={name="La recompensa del bosque",objectivesText={"Recoge 8 bellotas ventosombra en el Bosque Ventosombra."}}
T[93165]={name="La misericordia no existe",objectivesText={"Consigue 5 orejas de cultores Al'Aketh en el Bosque Ventosombra, el Santuario de Akir o los Tierras Bajas de los Soplabayas."}}
T[93172]={name="Libera a los huecos",objectivesText={"Destruye 10 huecos ventosos en el Bosque Ventosombra."}}
T[93176]={name="Amiguitos por doquier",objectivesText={"Utilizando los objetos que contiene el kit de iniciación a la entomología, encuentra y atrapa un espécimen de tarántula arbórea, un gorgojo del heno y un recogedor de carne."}}
T[93224]={name="Tótems de los centauros tallados",objectivesText={"Consigue 5 tótems de los centauros tallados asesinando centauros de cualquier clan de Desolace y, luego, entrégaselos al capitán Pentigast en Punta de Nijel."}}
T[93225]={name="Tótems de los centauros tallados",objectivesText={"Consigue 5 tótems de los centauros tallados asesinando a centauros de cualquier clan de Desolace y, luego, entrégaselos a Gurda Ferocrín en el Campamento del Espíritu Errante."}}
T[93226]={name="Amistad comprada: Magram",objectivesText={"Lleva la bolsa de tótems al intendente de los Magram en el Poblado Magram de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Magram."}}
T[93227]={name="Amistad comprada: Gelkis",objectivesText={"Lleva la bolsa de tótems al intendente de los Gelkis en el Poblado Gelkis de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Gelkis."}}
T[93317]={name="Temporada de cangrejo",objectivesText={"Recoge 6 piezas de carne de reptador Canzalvaje."}}
T[93318]={name="SE BUSCA: Vulgara el Insaciable",objectivesText={"Mata a Vulgara el Insaciable en las Tierras Altas de Shen'dar y lleva su cabeza a Danarii Velobramido."}}
T[93319]={name="Piedras de viento birladas",objectivesText={"Quita 10 piedras de viento birladas a los bandidos de las Tierras Altas en las Tierras Altas de Shen'dar."}}
T[93320]={name="Defender las torres",objectivesText={"Preséntate ante Yorana Juncoventoso en la torre de vigilancia oriental de las Tierras Bajas de los Soplabayas."}}
T[93341]={name="Jardines Desolados",objectivesText={"Investiga los Jardines Desolados cerca de Shen'dralas y regresa con Mithera en el templo cercano."}}
T[93362]={name="¿Qué les pasó a mis peonías?",objectivesText={"Sacrifica las plantas en el Jardín Desolado y regresa con Mithera en Shen'dralas."}}
T[93394]={name="Encuentro con el magíster",objectivesText={"Encuentra al Magíster Kirandis dentro del templo de Shen'dralas."}}
T[93404]={name="Ruina y remordimiento",objectivesText={"Ve a Maraudon, recupera un vial de agua de Canto de la Tierra y llévaselo a Sinosauco en los Jardines Desolados de Desolace."}}
T[93429]={name="Sangre de mi sangre",objectivesText={"Mata a 10 Perdidos en el Retiro Fangoso."}}
T[93430]={name="Recuperar el cebo",objectivesText={"Encuentra al pescador Perdido que ha robado el cebo de Pelluk y devuélveselo."}}
T[93443]={name="El cajón de transporte perdido",objectivesText={"Entrégale el cajón de transporte perdido a Friz Chispachás en Puerto Polvofusil, en Clarofluvial."}}
T[93450]={name="Problemas fantasmales",objectivesText={"Toma la espada sin terminar de Vindael y descubre cómo transportarla al reino espiritual. Luego, llévale el filo fantasmal a Shen'dralas."}}
T[93459]={name="Más orejas Al'Aketh"}
T[93461]={name="La Aldea Shen'dar",objectivesText={"Habla con Rathiril Lanzasol y Coriella Brisa Calmada en la Aldea Shen'dar."}}
T[93464]={name="El mago visitante",objectivesText={"Busca al mago en Desolace con conocimientos sobre el poder de la draenetista."}}
T[93465]={name="Notas sobre la draenetista",objectivesText={"Recoge las notas sobre la draenetista de Gimashi y llévaselas a Azore Aldamort."}}
T[93546]={name="Mena de hierro espectral",objectivesText={"Busca depósitos de hierro espectral en Shen'dralas y recoge 10 menas de hierro espectral. Cuando hayas encontrado suficientes, regresa con Vindael en Shen'dralas."}}
T[93552]={name="Cosecha de piedras de viento",objectivesText={"Reúne 15 cúmulos de piedras de viento de las piedras de viento en bruto en la Arboleda Thendal."}}
T[93568]={name="Collar parcialmente digerido",objectivesText={"Regresa el collar parcialmente digerido a alguien que sepa sobre él. Probablemente, lo puedes encontrar en Shen'dralas o en sus alrededores, en Desolace."}}
T[93585]={name="Bendita tu Luz",objectivesText={"Escolta al Padre Tuttle hasta el Puerto."}}
T[93594]={name="El mensaje del bosque",objectivesText={"Encuentra a Sinosauco en los Jardines Desolados en Shen'dralas en Desolace."}}
T[93644]={name="El diario ajado",objectivesText={"El texto da a entender que el autor de este diario podría estar en algún lugar de Shen'dralas."}}
T[93663]={name="Perdido en tránsito",objectivesText={"Busca al mensajero perdido y asegúrate de que el envío de Dar llega al Puerto."}}
T[93678]={name="Notas resumidas sobre la draenetista",objectivesText={"Llévale las notas transcritas de Azore a Magtoor en el Puerto, en el Pantano de las Penas."}}
T[93679]={name="Visiones de otro",objectivesText={"Contempla la visión de Onku con Magtoor."}}
T[93680]={name="La llave de la ciudad",objectivesText={"Consigue la llave de las cloacas de Dalaran para el magus Wordeen Vacuamirada en Molino Tarren."}}
T[93684]={name="El Encontrado",objectivesText={"Encuentra al draenei que está buscando draenetista en las Tierras Devastadas."}}
T[93685]={name="Al servicio de Kum'isha"}
T[93735]={name="El constructo roto",objectivesText={"Encuentra a Riaani Brisanoche en la zona oeste de Valanaar."}}
T[93736]={name="Espíritus no deseados",objectivesText={"Consigue 10 esencias de hueco ventoso en el Bosque Ventosombra."}}
T[93737]={name="El constructo roto",objectivesText={"Habla con Riaani Brisanoche y escucha lo que tiene que decirte."}}
T[93738]={name="El constructo roto",objectivesText={"Vuelve a Valanaar a informar a Ayessa Cantoalba."}}
T[93739]={name="Explorar la Horda",objectivesText={"Habla con Nazgrel en el Fuerte Grommash para que te dé indicaciones. Úsalas para localizar a Vol'jin, Cairne Pezuña de Sangre y Lady Sylvanas Brisaveloz y hablar con ellos."}}
T[93740]={name="Sangre por sangre",objectivesText={"Consigue 10 talismanes de piedra de viento de los cadáveres de los cultores Al'Aketh en los Tierras Bajas de los Soplabayas."}}
T[93746]={name="Una respuesta firme",objectivesText={"Planta cara a Belathaan Deseo Claro en el camino hacia el Santuario de Akir."}}
T[93786]={name="Un mensaje sangriento",objectivesText={"Asesina a 12 mozos de labranza de Campoarroyo y luego vuelve a hablar con Krom'rosh."}}
T[93787]={name="Botín en la granja",objectivesText={"Roba 6 bolsas para pienso de la granja de la Alianza en Campoarroyo y luego regresa con Krom'rosh."}}
T[93788]={name="Hojas prestadas",objectivesText={"Hazte con 10 hachas de leñador en el Aserradero de Turner y entrégaselas a Kreza Espinoscura en Rog'mar."}}
T[93791]={name="Hablar con Belann",objectivesText={"Habla con Belann Vientomadera en Valanaar."}}
T[93797]={name="Ramas en el viento",objectivesText={"Llévale una rama imbuida de viento a Belann Vientomadera en Valanaar."}}
T[93835]={name="La confrontación con Lorthuna",objectivesText={"Usa el portal a las Agujas Rohashi en lo alto y únete a Elaadrin Vendaval del Atardecer y a Ayessa Cantoalba en su enfrentamiento contra la Suma sacerdotisa Lorthuna."}}
T[93836]={name="El destino de Zephras",objectivesText={"Ve a Valanaar y habla con Talaanis Cantosombrío."}}
T[93926]={name="La torre occidental",objectivesText={"Encuentra al pacificador Vaaniel en la torre de vigilancia occidental."}}
T[93927]={name="Una última petición",objectivesText={"Recoge la nota que has encontrado junto al pacificador y léela para decidir qué hacer a continuación."}}
T[93948]={name="Entrega el sello",objectivesText={"Entrega el sello de la familia Cantosombrío a Talaanis Cantosombrío en Valanaar."}}
T[93949]={name="Vigilados",objectivesText={"Mata saltanubes en Valanaar hasta que hayas eliminado 8 saltanubes encantados."}}
T[93951]={name="Belleza de un plumazo",objectivesText={"Reúne 8 plumas de hipogrifo en las Tierras Altas de Shen'dar."}}
T[93958]={name="El Sagrario Interior",objectivesText={"Habla con Valennia Puñotormenta en el Sagrario Interior del Santuario de Akir."}}
T[93963]={name="Explorar la Alianza",objectivesText={"Habla con Randal Emersonen el Castillo de Ventormenta para que te dé indicaciones. Úsalas para localizar al rey Magni Barbabronce, al manitas mayor Mekkatorque y a Tyrande Susurravientos y hablar con ellos."}}
T[93976]={name="Comerciante goblin",objectivesText={"Entrega el arma a la conocida de Kreza Espinoscura en los muelles al este de Rog'mar."}}
T[94003]={name="El baluarte Rompecielos",objectivesText={"Arrebátale el baluarte Rompecielos a Zaal Escudo de Tormenta en el Santuario de Akir."}}
T[94006]={name="El gran espíritu de Ursera",objectivesText={"Habla con Urs'endris cerca de las cascadas al noreste de Valanaar."}}
T[94007]={name="Domar a la bestia",objectivesText={"Ve a Valanaar e informa a Quel'ana Prestovendaval."}}
T[94013]={name="Domar a la bestia",objectivesText={"Utiliza la fusta de domador para domar a un vuldren alfa en las Tierras Bajas de los Soplabayas. Practica tus habilidades y después devuélvele la fusta de domador a Quel'ana Prestovendaval, que está en Valanaar."}}
T[94050]={name="Entrenar a la bestia",objectivesText={"Habla con Quel'dora Prestovendaval en Valanaar."}}
