T[96104]={name="La canción del zancaalta",objectivesText={"Llévale un pico de zancaalta intacto a Neza Sangrocico en Rog'mar."}}
T[96105]={name="El rey de las Llanuras Salvajes",objectivesText={"Usa la llamada del zancaalta para atraer al líder de la manada de leones. Mata a la bestia y llévale su piel a Neza Sangrocico en Rog'mar."}}
T[96107]={name="Plumas letales",objectivesText={"Llévale 6 plumas de águila ratonera de las llanuras a Neza Sangrocico en Rog'mar."}}
T[96108]={name="Puntas envenenadas",objectivesText={"Llévale 4 muestras de veneno de víbora del claro a Neza Sangrocico en Rog'mar."}}
T[96109]={name="El carcaj de un cazador",objectivesText={"Consigue 6 pieles de león preciadas para Neza Sangrocico en Rog'mar."}}
T[96125]={name="Un poquito de ayuda",objectivesText={"Encuentra a Dunston Willis entre los ogros de Bolder'ok."}}
T[96126]={name="Prisionero de los ogros",objectivesText={"Encuentra a Gronok el Carnicero, mátalo y llévale a Dunston la llave de sus grilletes."}}
T[96130]={name="Chakuyak",objectivesText={"Derrota a Chakuyak y trae su pelambre."}}
T[96137]={name="Daga de Ira",objectivesText={"Derrota a 10 devastadores negros jóvenes y a 7 devastadores negros. Después, vuelve con Sirra Von'Indi en Villa Oscura a por más información."}}
T[96138]={name="Arco de Merrick",objectivesText={"Derrota a 8 guerreros Puñastilla y a 4 capataces Puñastilla y vuelve con Sirra Von'Indi en Villa Oscura para obtener más información."}}
T[96139]={name="La familia Valor",objectivesText={"Investiga el Cerro del Cuervo por si ves algo de interés y vuelve con Sirra Von'Indi en Villa Oscura."}}
T[96204]={name="La cólera de la Formavientos",objectivesText={"Acompaña a Lumina Vientocantor y ayúdala a escapar del Castillo de Fenris."}}
T[96222]={name="El khan Hratha",objectivesText={"Entrega el trozo de llave Maraudine a Umarak en Desolace."}}
T[96241]={name="Un veneno extraordinario",objectivesText={"Usa el extractor de toxinas para reunir 5 muestras de toxina de altopenumbra de los cadáveres mordisqueados en Altopenumbra."}}
T[96259]={name="Defender a los muertos",objectivesText={"Mata a 10 proles altopenumbra y a 5 soldados altopenumbra."}}
T[96260]={name="Más fuerte que el acero",objectivesText={"Consigue 3 hebras de seda cristalina de tejedoras altopenumbra."}}
T[96261]={name="La madre de linaje",objectivesText={"Mata a la madre de linaje Valraxx en Altopenumbra."}}
T[96264]={name="Ayuda elemental",objectivesText={"Derrota a Chargla Filonavaja en Horado Rajacieno y consigue información acerca de los planes de los jabaespines."}}
T[96294]={name="Una verdad más oscura",objectivesText={"Llévale la carta que recuperaste de la madre de linaje Valraxx a Muln Furiatierra en la Meseta de Miracielos."}}
T[96339]={name="Recompensa de legado: Réplica de rifle de aire comprimido de Forjaz"}
T[96390]={name="Arráncalos de raíz",objectivesText={"Mata a 10 espías Hierro Negro en Dun Morogh."}}
T[96391]={name="Mapa subterráneo",objectivesText={"Entrega el mapa Hierro Negro al videnterra Farsen en Dun Morogh."}}
T[96392]={name="La vigilancia de Farsen",objectivesText={"Habla con el Videnterra Farsen y pídele que te deje hacer uso de su visión lejana para observar la amenaza Hierro Negro."}}
T[96393]={name="Incursión en la Antigua Forjaz",objectivesText={"Entra en el Salón de los Feudales bajo Antigua Forjaz y hazte con la cabeza de Durgen Martillo Funesto."}}
T[96394]={name="Los muertos sin descanso",objectivesText={"Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar."}}
T[96395]={name="Un agravio antiguo",objectivesText={"Devuelve el espíritu de Faldrim Yunquemar a su descanso eterno y luego vuelve con el auxiliar fantasmal en el Salón de los Feudales."}}
T[96403]={name="Reliquias importantes",objectivesText={"Recupera 8 reliquias enanas en el Salón de los Feudales."}}
T[96408]={name="Un visitante en Dun Morogh",objectivesText={"Investiga el campamento sobre la Cantera de Gol'Bolar."}}
T[96604]={name="El gran mundo exterior",objectivesText={"Siéntate junto a la hoguera básica de Brakk y espera hasta recibir el beneficio Descanso mejorado."}}
T[96605]={name="El gran mundo exterior",objectivesText={"Siéntate junto a la hoguera básica de Kaga y espera hasta recibir el beneficio Descanso mejorado."}}
T[96606]={name="El gran mundo exterior",objectivesText={"Siéntate junto a la hoguera básica de Lyreena y espera hasta recibir el beneficio Descanso mejorado."}}
T[96607]={name="El gran mundo exterior",objectivesText={"Siéntate junto a la hoguera básica de Eleanor y espera hasta recibir el beneficio Descanso mejorado."}}
T[96608]={name="El gran mundo exterior",objectivesText={"Siéntate junto a la hoguera básica de Eric y espera hasta recibir el beneficio Descanso mejorado."}}
T[96609]={name="El sabor del hogar",objectivesText={"Lleva 10 botellas de fulgorvino de Lunargenta a Arille Mirada Azur en la Ciudad de Dalaran."}}
T[96626]={name="Acampada para novatos: cocinar",objectivesText={"Habla con Tomas en Villadorada para aprender a cocinar."}}
T[96627]={name="El aventurero",objectivesText={"Habla con Sam Zarzaparrilla cerca de Villadorada."}}
T[96628]={name="El aventurero",objectivesText={"Entrega el fardo de suministros a Eric Martillo Radiante cerca de Kharanos."}}
T[96629]={name="Acampada para novatos: cocinar",objectivesText={"Habla con Gremlock Pilsnor en Kharanos para aprender a cocinar."}}
T[96630]={name="El aventurero",objectivesText={"Llévale el diario a Lyreena Hoja Umbría cerca de Dolanaar."}}
T[96634]={name="Acampada para novatos: cocinar",objectivesText={"Habla con Zarrin en Dolanaar para aprender a cocinar."}}
T[96638]={name="El aventurero",objectivesText={"Habla con Raan Vientosalvaje cerca de la Aldea Shen'dar."}}
T[96646]={name="Acampada para novatos: cocinar",objectivesText={"Habla con Zerril Brisaleve en la Aldea Shen'dar y aprende a cocinar."}}
T[96652]={name="El aventurero",objectivesText={"Llévale el diario a Brakk cerca de Cerrotajo."}}
T[96655]={name="Acampada para novatos: cocinar",objectivesText={"Habla con el cocinero Torka en Cerrotajo para aprender a cocinar."}}
T[96656]={name="La aventurera",objectivesText={"Habla con Eleanor Tembleque cerca de Rémol."}}
T[96658]={name="Acampada para novatos: cocinar",objectivesText={"Habla con William Pickman en Rémol para aprender a cocinar."}}
T[96659]={name="La aventurera",objectivesText={"Entrega el fardo de suministros a Kaga Pezuña Salvaje cerca del Poblado Pezuña de Sangre."}}
T[96661]={name="Acampada para novatos: cocinar",objectivesText={"Habla con Pyall Trancosilencio en el Poblado Pezuña de Sangre para aprender a cocinar."}}
T[96770]={name="La cabeza del médico brujo",objectivesText={"Mata al médico brujo Zum'Rah y llévale su cabeza al archimago Lan'dalock en Dalaran."}}
T[96771]={name="La venganza del Altonato",objectivesText={"Viaja al Bastión Krol'dok y mata a Zalfan Umbraluna."}}
T[96773]={name="El ojo del Gélido",objectivesText={"Recupera el ojo del Gélido en la Zahúrda Rajacieno."}}
T[96774]={name="Un antiguo ídolo Gurubashi",objectivesText={"Recupera un antiguo ídolo Gurubashi en la Ciudad Sumergida."}}
T[96782]={name="Extracción encubierta",objectivesText={"Encuentra la hoja de la Casa Perenolde y la égida real de Perenolde entre las ruinas de Alterac. Cuando termines, llévaselas a Myrokos Silenforma."}}
T[96784]={name="Maestro del disfraz",objectivesText={"Mientras estás disfrazado como un miembro de la Hermandad, encuentra a alguien dentro del Castillo de Stromgarde que sepa sobre el acuerdo secreto."}}
T[96800]={name="Fuera de plazo",objectivesText={"Recupera el libro \"La magia perdida de los maestros de runas\" para el Monasterio Escarlata."}}
T[96821]={name="Pies, para qué os quiero",objectivesText={"Mata a 6 trepadores crestasombra y a 6 rondadores crestasombra en la parte sur de Durotar. Después, informa a Gar'thok en Cerrotajo."}}
T[96822]={name="Por honor",objectivesText={"Consigue el hacha de batalla de asaltante, el arco de asaltante y el escudo de asaltante a las afueras del Fuerte de Tiragarde y devuélveselo todo a Turroc en Cerrotajo."}}
T[96825]={name="La fruta que devuelve el mordisco",objectivesText={"El cocinero Torka de Cerrotajo quiere que recojas 8 frutos pera espinosa en las Tierras Crines de Acero que hay al oeste de la ciudad."}}
T[96873]={name="Dolor cervical",objectivesText={"Pa'zula, en el Poblado Sen'jin, quiere que reúnas 3 de residuo luminoso. Se puede obtener residuo luminoso desencantando los colgantes embrujados que dejan caer los trols en las Islas del Eco."}}
T[96874]={name="Hacha de espinazo",objectivesText={"Ug'thok en Orgrimmar quiere que consigas 5 espinazos deteriorados de las bestias que hay en Monte del Trueno y 5 piedras de pulir férreas."}}
T[96875]={name="Las bestias del Monte del Trueno",objectivesText={"Kamari en Orgrimmar quiere que consigas 5 pellejos de lagarto resistentes de las bestias que hay en Monte del Trueno y 2 pellejos ligeros curados."}}
T[96876]={name="Bolsa perdida de Ukor",objectivesText={"Devuélvele la bolsa a Ukor en la parte sur de Durotar."}}
T[96877]={name="Pezuña de Halikor",objectivesText={"Entrega la pezuña de Halikor en Orgrimmar."}}
T[96895]={name="El emisario Argenta",objectivesText={"Encuentra al miembro de El Alba Argenta cerca de la entrada de Entrañas."}}
T[96896]={name="Una causa justa",objectivesText={"Observa la conversación entre Danitha Morr y Leonid Barthalomew el Venerado."}}
T[96897]={name="El Culto de los Malditos",objectivesText={"Mata a 8 neófitos oscuros y a 8 déspotas oscuros en los Claros de Tirisfal."}}
T[96898]={name="Remanentes de guerra",objectivesText={"Consigue 12 trozos de cristal necrótico en los Claros de Tirisfal."}}
T[96899]={name="Fortaleza de Bandarion",objectivesText={"Reúnete con Leonid Barthalomew en la Fortaleza de Bandarion, en los Claros de Tirisfal."}}
T[96984]={name="El corazón de la perturbación",objectivesText={"Recupera la mota Arcana en la Ciudad de Dalaran para el magus Wordeen Vacuamirada, en Molino Tarren."}}
T[96986]={name="El Caballero de la Tumba",objectivesText={"Derrota a Atrexis el Caballero de la Tumba en la Ciudad de Dalaran. Después, informa a Melisara en Molino Tarren."}}
T[96987]={name="Educación oportunista",objectivesText={"Consigue La fundación de Dalaran en la Ciudad de Dalaran para Rexxie Aferracobre, en la entrada a las cloacas."}}
T[96988]={name="Fuente de poder",objectivesText={"Consigue 6 núcleos de centinela agrietados en la Ciudad de Dalaran para el doctor Martin Felben de Entrañas."}}
T[96997]={name="Un corcel en la muerte como lo fue en vida",objectivesText={"Observa a los caballos de montar no-muertos y elige tu primera montura."}}
T[97003]={name="Chol'aruk el Devorador",objectivesText={"Lleva la cabeza de Chol'aruk a Gur'ak en Los Baldíos."}}
T[97005]={name="Chol'aruk el Devorador",objectivesText={"Lleva la cabeza de Chol'aruk a Bainham en Los Baldíos."}}
T[97047]={name="Cocinero entre rejas",objectivesText={"Busca en la Base de Kurzen la llave que abre la jaula de Wendel y un disfraz con el que pueda salir sin levantar sospechas."}}
T[97048]={name="Vuelta al puerto",objectivesText={"Habla con la capitana Aransas en Bahía del Botín."}}
T[97130]={name="Antiguos secretos Gurubashi",objectivesText={"Recupera un antiguo ídolo Gurubashi en la Ciudad Sumergida."}}
T[97194]={name="Aprendiendo a andar",objectivesText={"Aprende la habilidad Aprendiz jinete de Kildar."}}
T[97196]={name="El ojo del Gélido",objectivesText={"Recupera el ojo del Gélido en la Zahúrda Rajacieno."}}
T[97203]={name="Lecciones de monta",objectivesText={"Aprende la habilidad Aprendiz jinete de Velma Warnam."}}
T[97220]={name="El favor de Philmor",objectivesText={"Lleva el envío a la torre de entrada a la entrada del almacén ubicada en la tienda Queso de Trias, en el Distrito de Mercaderes."}}
T[97222]={name="Bienes de la torre de entrada",objectivesText={"Lleva el envío a la torre de entrada en el piso de arriba de la tienda Queso de Trias y déjalo en la puerta."}}
T[97223]={name="Matriarca Garrasangre",objectivesText={"Llévale los huevos de la matriarca Garrasangre a Xar'Ti, en el Poblado Sen'jin."}}
T[97225]={name="Ídolos loa olvidados",objectivesText={"Reúne 8 ídolos loa olvidados en las Islas del Eco. Llévaselos a maese Gadrin al Poblado Sen'jin."}}
T[97234]={name="Sala de lectura",objectivesText={"Lleva el material de lectura envuelto a la biblioteca de Ventormenta."}}
T[97236]={name="Colmillo de Githyiss",objectivesText={"Entrega el colmillo de Githyiss a alguien que esté interesado en el estudio de las arañas en Aldrassil."}}
T[97237]={name="Estanterías a tu disposición",objectivesText={"Encuentra todos los materiales de lectura que se encuentran por la biblioteca y vuelve con Roy Lewells en el Parque de Ventormenta."}}
T[97242]={name="El popurrí de Yelmak",objectivesText={"Recoge algunos esquejes de las apiáceas y de las eneas que crecen alrededor del estanque del Valle del Honor y entrégaselos a Kor'geld en la tienda de Alquimia y pociones de Yelmak."}}
T[97243]={name="La llamada del fuego",objectivesText={"Llévale la antorcha de la llama latente a Olariaan Ardeveloz en el santuario de las llamas que está en las Tierras Bajas de los Soplabayas."}}
T[97244]={name="La llamada del fuego",objectivesText={"Asesina al sacerdote del cielo Faladiel en las Tierras Bajas de los Soplabayas y consigue su corazón."}}
T[97245]={name="La llamada del fuego",objectivesText={"Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota a este espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Ardeveloz en las Tierras Bajas de los Soplabayas una vez que te alces con la victoria."}}
T[97246]={name="A plato puesto",objectivesText={"Visita la Fosa de lava de Borstan y dile que Thatog quiere que le entregues personalmente el almuerzo de Migi."}}
T[97249]={name="Comida favorita",objectivesText={"Llévale el almuerzo a Migi detrás del Fuerte Grommash."}}
T[97250]={name="Culpa incorrecta, corregida",objectivesText={"Mata a los soldados de la Alianza que han invadido Los Baldíos en la frontera con el Marjal Revolcafango y luego vuelve con el bruto Logmar en el Campamento Taurajo."}}
T[97253]={name="Volver con piezas de una pieza",objectivesText={"Consigue 5 puñados de piezas complicadas del campamento pirata superior que hay al sur de Trinquete y luego vuelve con Desdio el Desdichado en Trinquete."}}
T[97257]={name="La llamada del fuego",objectivesText={"Espera a que Olariaan empiece el ritual en el blandón de ofrendas y sigue sus instrucciones.","","Debes entregar la Llama eterna en Valanaar antes de que se agote el tiempo."}}
T[97263]={name="Ha llegado tu paquete",objectivesText={"Entrega a Eldrun su paquete perdido."}}
T[97265]={name="Odio al Odio Feroz",objectivesText={"Derrota a sátiros Odio Feroz en Sargeron, Desolace, y luego vuelve con Aka'rai en la Aldea Cazasombras."}}
T[97275]={name="Elaboración a fuego lento",objectivesText={"Dale la poción de Yelmak a Whuut."}}
T[97277]={name="Grund y Gozwin",objectivesText={"Busca el campamento de Grund y Gozwin en las colinas que hay al noroeste. Recupera el registro de mecánico de Gozwin y mata al leopardo de la nieve merodeador."}}
T[97279]={name="Armas extraviadas",objectivesText={"Recoge 6 armas de entrenamiento abandonadas y llévaselas a Kzan Trallafusta en El Cubil."}}
T[97281]={name="Una tormenta inminente",objectivesText={"Llévale el orbe de tormenta sin brillo a Rezlak, cerca del Barranco Árido."}}
T[97282]={name="Potencial tormentoso",objectivesText={"Llévale 5 órganos de truenagarto cargados a Rezlak, cerca del Barranco Árido."}}
T[97284]={name="Venganza de Vahlarriel",objectivesText={"Mata a los orcos del Filo Ardiente de la Fortaleza del Hacha de Trueno de Desolace y después vuelve con Vahlarriel Destripademonios en Punta de Nijel."}}
T[97286]={name="Acceso a la investigación"}
T[97287]={name="Negociaciones astutas",objectivesText={"Habla con la imagen de la archimaga Modera cerca de Dalaran."}}
T[97288]={name="Tormento interminable",objectivesText={"Entrega la cabeza abominable al maestro boticario Faranell en Entrañas."}}
T[97289]={name="Tormento interminable",objectivesText={"Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas."}}
T[97290]={name="Tormento interminable",objectivesText={"Informa de tus hallazgos al maestro boticario Faranell de Entrañas."}}
T[97291]={name="Tormento interminable",objectivesText={"Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas."}}
T[97292]={name="Tormento interminable",objectivesText={"Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell."}}
T[97326]={name="Descanso rocoso",objectivesText={"Llévale 8 rocas suaves a Thra detrás del Fuerte Grommash."}}
T[97328]={name="Cualquier objeto de valor",objectivesText={"Recupera 8 envíos robados de las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévaselos a alguien en Bahía del Botín."}}
T[97329]={name="¿Dónde está la llave?",objectivesText={"Consigue la llave primitiva de los trols en las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévasela a Zimmix Escupechispa."}}
T[97331]={name="La gran evasión de Zimmix",objectivesText={"Escolta a Zimmix Escupechispa fuera de las Ruinas de Zul'Kunda e informa al jefe de embarcadero Lozgil del éxito de tu rescate en Bahía del Botín."}}
T[97332]={name="Tropezar dos veces con la misma piedra",objectivesText={"Entrega el paquete pedido dos veces al maestro de los muelles Silbazumbido en Puerto Polvofusil, en Clarofluvial."}}
T[97386]={name="La ofensa de Grom'gol",objectivesText={"El comandante del Campamento Grom'gol, Aggro'gosh, quiere que mates ogros en el Túmulo Ogro Mosh'Ogg."}}
T[97405]={name="Quejas por ruidos",objectivesText={"Knaz Flamerrada quiere que mates 3 creaconjuros Mosh'Ogg, 3 belicistas Mosh'Ogg, 3 aplastadores Mosh'Ogg y 3 chamanes Mosh'Ogg en el Túmulo Ogro Mosh'Ogg."}}
T[97420]={name="Reduce, reutiliza, reconcilia",objectivesText={"Consigue 4 bidones de petróleo de las operaciones de Ventura y Cía. en el Lago Nazferiti y vuelve con Knaz Flamerrada en la Vega de Tuercespina."}}
T[97453]={name="Mala hierba segada",objectivesText={"Mata 6 hierbas carnívoras al sur de Grom'gol e informa a la madre de Gemmil."}}
T[97485]={name="Tradiciones de la cima",objectivesText={"Compra un fardo de hierbas a Nida la herborista, un fardo de ramas de cedro a Nata la proveedora de encantamientos, hilo tendinoso a Mahu el proveedor de suministros de peletería, y sílex y yesca ceremoniales a Naal el proveedor de artículos de cocina.","","Combina los objetos y esparce el incienso desde el Alto de los Cazadores."}}
T[97538]={name="Pigmentos para pinturas",objectivesText={"Tah Pezuña Invernal en Cima del Trueno quiere 30 vainas de hierbaoscura del Lago Mirkfallon."}}
T[97539]={name="Suturas sedosas",objectivesText={"Entrega 12 sedas de araña quirúrgicas al doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi."}}
T[97558]={name="Pieles para los Renegados",objectivesText={"Lleva 8 membranas de ala de murciumbrío, 6 pellejos de can oscuro y 3 piel de múrloc Anca Vil a Shelene Rhobart."}}
T[97583]={name="CONTONEOS.",objectivesText={"Compra fango de babosa nutritivo y vuelve con tu inquieta y amistosa babosa. Si parece cansada, baila con ella de nuevo para llamar su atención."}}
T[97617]={name="Comprobaciones de seguridad",objectivesText={"Llévale 8 artefactos sin estudiar, un casco de minería de la Liga de Expedicionarios y un azadón prístino a Dorgaron, que está en la frontera entre Loch Modan y las Tierras Inhóspitas."}}
T[97663]={name="Suministros y estudios",objectivesText={"Asesina a los ogros en Terraseca para recuperar los suministros robados de Mus'hale y úsalos para calcar las piedras grabadas en los alrededores. Al terminar, regresa con Mus'hale en Kargath."}}
T[97884]={name="El arsenal de Clarosol",objectivesText={"Viaja a Clarosol en Clarofluvial y recupera el escrito Técnicas de herrería de la familia Tremayne."}}
T[97891]={name="Veloz corredor de pociones",objectivesText={"Llévale una poción inestable al doctor Martin Felben en El Apothecarium antes de que se acabe el tiempo."}}
T[97894]={name="Asuntos en Auberdine",objectivesText={"Comprueba cómo está Gorbold Mano de Acero en Auberdine, en Costa Oscura.","","Borgus ha mencionado que puedes coger un barco en el muelle más al sur del Puerto de Ventormenta."}}
T[97899]={name="Acampada para novatos: alquimia",objectivesText={"Habla con Whuut en Orgrimmar para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
T[97900]={name="Acampada para novatos: herrería",objectivesText={"Habla con Dwukk en Cerrotajo para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
T[97901]={name="Acampada para novatos: encantamiento",objectivesText={"Habla con Jhag en Orgrimmar para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
T[97902]={name="Acampada para novatos: ingeniería",objectivesText={"Habla con Mukdrak en Cerrotajo para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
