T[97977]={name="La llamada de la naturaleza",objectivesText={"Llévale 4 tótems Tuercepinos a Tarindrella."}}
T[97979]={name="La diosa provee",objectivesText={"Lanza Luz de Elune y Fusión de las Sombras."}}
T[97985]={name="Corazones atronadores",objectivesText={"Mata a Corazón Atronador en Las Mil Agujas y consigue su corazón."}}
T[98013]={name="Fuerzas henchidas",objectivesText={"Elimina a 12 mirmidones Escama Tormentosa, 8 hechiceras Escama Tormentosa y 6 guerreros Escama Tormentosa para Arbal en el Páramo de los Ancianos."}}
T[98021]={name="Viaje a la Colina del Centinela",objectivesText={"Preséntate ante Gryan Mantorrecio en la Colina del Centinela, en los Páramos de Poniente."}}
T[98024]={name="Viaje a El Cruce",objectivesText={"Preséntate ante Thork en El Cruce de Los Baldíos."}}
T[98025]={name="SE BUSCA: Jai'vhanel",objectivesText={"Encuentra y mata al búho conocido como Jai'vhanel y llévate una de sus plumas. Lo vieron por última vez al norte de las ruinas de Ameth'Aran, cerca del pie de la montaña. Informa de la muerte de Jai'vhanel a la centinela Glynda Nal'Shea en Auberdine."}}
T[98027]={name="El collar de media luna resplandeciente",objectivesText={"Entrégale el collar de media luna a Maliynn en Astranaar."}}
T[98028]={name="Barón Marinous",objectivesText={"Llévale el globo de agua turbia a Onu en el Páramo de los Ancianos, en Costa Oscura."}}
T[98042]={name="Todo son risas hasta que...",objectivesText={"Consigue un ojo incomparable de un discípulo o un matón Crepuscular en la Espada del Maestro, en Costa Oscura. Después busca a alguien en Auberdine que esté dispuesto a hacerse cargo de él."}}
T[98046]={name="La corona de la Tierra",objectivesText={"Llévale el recipiente drenado a Lariia en el Templo de la Luna, en Darnassus."}}
T[98059]={name="El tesoro de Trabalomas",objectivesText={"Coloca la petición de compañía sellada sobre la mesa de contabilidad del ayuntamiento de Trabalomas."}}
T[98065]={name="La corona de la Tierra",objectivesText={"Lleva los restos de la poza de la luna a Tyrande Susurravientos en el Templo de la Luna, en Darnassus."}}
T[98067]={name="Ojos de los centinelas",objectivesText={"Coloca búhos centinela en la entrada que lleva a las profundidades del Fuerte Cenarion, en el Banco de Darnassus, en la posada del Bancal del Artesano y en la puerta de la ciudad para la centinela Dalia Filosol, que está en el Templo de la Luna de Darnassus."}}
T[98069]={name="Los suministros de Viento Libre robados",objectivesText={"Llévale 8 suministros de Viento Libre robados a Jandia en el Poblado Viento Libre."}}
T[98070]={name="Silenciar el chirrido",objectivesText={"Mata a 5 arpías estridentes, 5 arpías Malapluma estridentes y 5 arpías clamavientos estridentes."}}
T[98071]={name="El oficio de cervecero",objectivesText={"Entrega las botellas de varietales de Bajograjo en Dun Garok, que está al sureste de las Laderas de Trabalomas. Después, lleva de vuelta un saco de lúpulo de cerveza casera."}}
T[98072]={name="Crocos del cielo",objectivesText={"Consigue 8 escamas prístinas carmesíes y llévaselas a James Halloran en el Puerto de Menethil."}}
T[98093]={name="Un campo que despejar",objectivesText={"Sulhasa, en Los Baldíos del Sur, quiere que elimines a 7 lagartos tormenteros y a 7 acechadores Dentecenado en la zona para que pueda bajar del árbol sin peligro."}}
T[98094]={name="Asistencia a los exploradores",objectivesText={"La suma ejecutora Darthalia quiere que le entregues las nuevas órdenes al mortacechador Masoj, que se encuentra al sur de Molino Tarren, justo a las afueras de Dun Garok."}}
T[98095]={name="Ventajas valiosas",objectivesText={"El mortacechador Masoj necesita que coloques tres viales de apotecarios en los lugares claves de las Laderas de Trabalomas. Después, regresa con él."}}
T[98155]={name="Las pelambres de pestillejo prístinas",objectivesText={"Llévale 5 pelambres de pestillejo prístinas a Kristy Grant."}}
T[98189]={name="Devolver la Estatuilla",objectivesText={"Lleva la Estatuilla de Menethil al capitán Puñorrecio en el Castillo de Menethil."}}
T[98190]={name="Un amigo de la familia",objectivesText={"Lleva la Estatuilla de Menethil al alto señor Bolvar Fordragón en el Castillo de Ventormenta."}}
T[98191]={name="Un amigo de la familia",objectivesText={"Lleva la Estatuilla de Menethil a Lord Grisillo Quiebrasombras en la Catedral de la Luz."}}
T[98192]={name="Despellejar con cuidado y con destreza",objectivesText={"Llévale 8 pellejos de raptor intactos a Krak en el Poblado Murohelecho."}}
T[98197]={name="Botín de guerra",objectivesText={"Recupera 6 trozos de madera de Khaz Modan y 30 fragmentos de hierro de Khaz Modan del Puerto de Menethil para Valstag Quijahierro."}}
T[98208]={name="Flor de los cielos",objectivesText={"Recupera la Nord'el para Sylessa Susurro del Anochecer en el Puerto de Menethil."}}
T[98209]={name="Flor de los cielos",objectivesText={"Lleva la Nord'el a Thundris Tejevientos en Auberdine, en Costa Oscura.","","Sylessa te ha recomendado que cojas un barco en el Puerto de Menethil que te llevará hasta allí."}}
T[98216]={name="Comprender el presente",objectivesText={"Usa la piedra de Goaz cerca del guardián de Goaz y lleva la piedra angular titánica al prospector Whelgar."}}
T[98219]={name="Un teniente avergonzado",objectivesText={"Habla con el teniente Farren Orinelle en Costasur, en las Laderas de Trabalomas."}}
T[98221]={name="Desde las cenizas",objectivesText={"El capitán Puñorrecio del Castillo de Menethil quiere que destruyas 4 conjuntos de planes de ataque en el Campamento Dentellada."}}
T[98223]={name="Viejas costumbres",objectivesText={"Lleva el libro de hechizos andrajoso al capitán Puñorrecio en el Puerto de Menethil."}}
T[98230]={name="Esta era su tierra",objectivesText={"Sigue el camino para encontrar a Howin Plumamable al este del Puerto de Menethil."}}
T[98233]={name="La espada en el cieno",objectivesText={"Recupera la espada de entrenamiento de Jameson y llévasela al guardia Jameson."}}
T[98240]={name="Entrega de caja carmesí",objectivesText={"Entrega la caja carmesí a Howin Plumamable cerca del camino que hay al este del Puerto de Menethil."}}
T[98245]={name="Agujas de tajobuche",objectivesText={"Consigue 10 incisivos de tajobuche para Howin Plumamable."}}
T[98246]={name="Tiempos difíciles",objectivesText={"Consigue 12 huevos de tajobuche perfectos para Howin Plumamable."}}
T[98247]={name="Etiqueta de envíos",objectivesText={"Entrega la etiqueta de envíos a alguien de la sede comercial de la Autoridad Comercial de Azeroth en las Montañas Crestagrana."}}
T[98248]={name="Etiqueta de envíos",objectivesText={"Entrega la etiqueta de envíos a alguien del puesto comercial de Suministros y Logística de Durotar cerca de El Cruce, en Los Baldíos."}}
T[98251]={name="No pienso volver",objectivesText={"Mata 6 venados Necraste y 6 osos de Vallefresno y vuelve con Vax'ug Fuegoinquina al noroeste del Lago Cielo Estrellado."}}
T[98252]={name="Un camino vacío",objectivesText={"Muestra al ojo de Kilrogg de Va'xug el camino de vuelta a la carretera principal de Vallefresno."}}
T[98282]={name="Los peligros de la alquimia",objectivesText={"Consigue una glándula de acechador sin grietas de la Roca Thelgen para Caitlin Pastal en el Puerto de Menethil."}}
T[98283]={name="Carnicería",objectivesText={"Lleva la cabeza de Carnicería a Rethiel el Guardaverde en la Franja Verde."}}
T[98284]={name="Acampada para novatos: encantamiento",objectivesText={"Habla con Nasalanna Vientocantor en la Aldea Shen'dar para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
T[98285]={name="Campamento básico: Ingeniería",objectivesText={"Habla con el ermitaño extraño en Bosque Ventarrosombra para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad."}}
T[98286]={name="Acampada para novatos: encantamiento",objectivesText={"Habla con Nasalanna Vientocantor en la Aldea Shen'dar para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad."}}
T[98291]={name="Muerte a los Faucedraco",objectivesText={"Mata a 8 reivindicadores Faucedraco, 5 vinculadores de almas Faucedraco y 3 infiltrados Faucedraco en Retiro Faucedraco para Howin Plumamable."}}
T[98293]={name="Desarme forzado",objectivesText={"Consigue 30 piezas de armamento de Faucedraco en Retiro Faucedraco y llévaselas al capitán Puñorrecio en el Castillo de Menethil."}}
T[98297]={name="Detener el ciclo",objectivesText={"Mata al dragauro subyugado en las Puertas Faucedraco para Howin Plumamable."}}
T[98298]={name="La locura de Arugal",objectivesText={"Llévale 6 tapitas de huargen a Dalar Tejealba en El Sepulcro."}}
T[98299]={name="Detener la propagación",objectivesText={"Mata a 5 refugiados enfermos y a 5 refugiados demacrados para Dalar Tejealba en El Sepulcro."}}
T[98300]={name="Mensaje a Forjaz",objectivesText={"Entrega la misiva de Howin al rey Magni Barbabronce en Forjaz."}}
T[98310]={name="La forja del futuro",objectivesText={"Usa la piedra de Goaz cerca de Ados, Modr, Golm y Neru, y lleva sus corazones al prospector Whelgar."}}
